-- =============================================================================
-- 00097 — AI Workforce characters (8 Nov 2026)
--
-- Each AI role gets a CHARACTER: a name, a one-line persona, three strengths
-- and a portrait — the cast Kamal illustrated (six sheets, 36 characters).
-- The art lives in apps/hub/public/ai/characters/<role>.webp; the words live
-- here, in three languages, so nothing about a character is hard-coded.
--
-- Country: a row with country_code NULL is the default for every market; a
-- row with 'MY' or 'ID' overrides it for agents of that country (name, words
-- or portrait), so the cast can differ by country when the owner decides —
-- set from /admin/ai, never by deploy.
-- =============================================================================
create table public.ai_role_personas (
  id            uuid primary key default gen_random_uuid(),
  role_key      text not null references public.ai_roles(key) on delete cascade,
  country_code  text references public.countries(code),      -- null = default for all
  name          text not null,
  tagline       jsonb not null default '{}'::jsonb,           -- {en, ms, id}
  skills        jsonb not null default '{}'::jsonb,           -- {en: [..3], ms: [..], id: [..]}
  portrait_path text,
  avatar_path   text,
  updated_by    uuid references auth.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create unique index idx_ai_role_personas_role_country on public.ai_role_personas (role_key, coalesce(country_code, '*'));
create trigger ai_role_personas_updated_at before update on public.ai_role_personas
  for each row execute function public.set_updated_at();

alter table public.ai_role_personas enable row level security;
create policy "ai personas read" on public.ai_role_personas for select to authenticated using (true);
create policy "ai personas admin" on public.ai_role_personas for all to authenticated
  using (public.has_capability('ai.manage')) with check (public.has_capability('ai.manage'));
revoke all on public.ai_role_personas from anon, authenticated;
grant select, insert, update, delete on public.ai_role_personas to authenticated;

insert into public.ai_role_personas (role_key, name, tagline, skills, portrait_path, avatar_path) values
  ('ai_manager', 'Astra', '{"en":"Your command centre for the day — turns briefs into action, sets priorities and keeps the team aligned.","ms":"Pusat kawalan hari anda — menukar taklimat kepada tindakan, menetapkan keutamaan dan menyelaraskan pasukan.","id":"Pusat kendali hari Anda — mengubah brief menjadi tindakan, menetapkan prioritas dan menjaga tim selaras."}'::jsonb, '{"en":["Daily brief","Priorities","Team alignment"],"ms":["Taklimat harian","Keutamaan","Penyelarasan pasukan"],"id":["Brief harian","Prioritas","Keselarasan tim"]}'::jsonb, '/ai/characters/ai_manager.webp', '/ai/characters/ai_manager-avatar.webp'),
  ('owner_report_writer', 'Nova', '{"en":"Turns activity, enquiries and viewing updates into clear, professional owner reports.","ms":"Menukar aktiviti, pertanyaan dan kemas kini lawatan kepada laporan pemilik yang jelas dan profesional.","id":"Mengubah aktivitas, pertanyaan dan pembaruan kunjungan menjadi laporan pemilik yang jelas dan profesional."}'::jsonb, '{"en":["Owner updates","Weekly reports","Clear numbers"],"ms":["Kemas kini pemilik","Laporan mingguan","Angka yang jelas"],"id":["Pembaruan pemilik","Laporan mingguan","Angka yang jelas"]}'::jsonb, '/ai/characters/owner_report_writer.webp', '/ai/characters/owner_report_writer-avatar.webp'),
  ('document_summariser', 'Lyra', '{"en":"Reads and distils long documents you upload, highlighting key points, risks and next steps.","ms":"Membaca dan meringkaskan dokumen panjang yang anda muat naik, menonjolkan perkara utama, risiko dan langkah seterusnya.","id":"Membaca dan merangkum dokumen panjang yang Anda unggah, menyoroti poin utama, risiko dan langkah berikutnya."}'::jsonb, '{"en":["Key points","Risks","Next steps"],"ms":["Perkara utama","Risiko","Langkah seterusnya"],"id":["Poin utama","Risiko","Langkah berikutnya"]}'::jsonb, '/ai/characters/document_summariser.webp', '/ai/characters/document_summariser-avatar.webp'),
  ('lead_qualifier', 'Zayn', '{"en":"Scores and sorts new enquiries so you focus on the most promising leads first.","ms":"Menilai dan menyusun pertanyaan baharu supaya anda fokus pada prospek paling berpotensi dahulu.","id":"Menilai dan mengurutkan pertanyaan baru agar Anda fokus pada prospek paling menjanjikan lebih dulu."}'::jsonb, '{"en":["Intent score","Reasoned ranking","Never hides a lead"],"ms":["Skor niat","Susunan beralasan","Tidak menyembunyikan prospek"],"id":["Skor niat","Urutan beralasan","Tidak menyembunyikan prospek"]}'::jsonb, '/ai/characters/lead_qualifier.webp', '/ai/characters/lead_qualifier-avatar.webp'),
  ('duplicate_detector', 'Vex', '{"en":"Spots and flags potential duplicate leads — like the same phone number across different enquiries.","ms":"Mengesan dan menandakan prospek berganda — seperti nombor telefon yang sama dalam pertanyaan berbeza.","id":"Mendeteksi dan menandai prospek ganda — seperti nomor telepon yang sama di pertanyaan berbeda."}'::jsonb, '{"en":["Duplicate check","Same-number alerts","Clean pipeline"],"ms":["Semakan berganda","Amaran nombor sama","Saluran bersih"],"id":["Cek duplikat","Peringatan nomor sama","Pipeline bersih"]}'::jsonb, '/ai/characters/duplicate_detector.webp', '/ai/characters/duplicate_detector-avatar.webp'),
  ('silence_radar', 'Echo', '{"en":"Keeps an eye on quiet leads and flags those going cold, so no opportunity slips away.","ms":"Memantau prospek yang senyap dan menandakan yang semakin sejuk, supaya tiada peluang terlepas.","id":"Mengawasi prospek yang diam dan menandai yang mulai dingin, agar tak ada peluang terlewat."}'::jsonb, '{"en":["Quiet leads","Cold alerts","Timely nudges"],"ms":["Prospek senyap","Amaran sejuk","Peringatan tepat masa"],"id":["Prospek diam","Peringatan dingin","Dorongan tepat waktu"]}'::jsonb, '/ai/characters/silence_radar.webp', '/ai/characters/silence_radar-avatar.webp'),
  ('reply_drafter', 'Mira', '{"en":"Crafts friendly, professional replies to enquiries across WhatsApp and e-mail, ready to edit and send.","ms":"Menyediakan balasan mesra dan profesional untuk pertanyaan melalui WhatsApp dan e-mel, sedia disunting dan dihantar.","id":"Menyusun balasan ramah dan profesional untuk pertanyaan lewat WhatsApp dan e-mail, siap diedit dan dikirim."}'::jsonb, '{"en":["Client replies","Enquiry handling","Fast & on-brand"],"ms":["Balasan pelanggan","Pengendalian pertanyaan","Pantas & konsisten"],"id":["Balasan klien","Penanganan pertanyaan","Cepat & konsisten"]}'::jsonb, '/ai/characters/reply_drafter.webp', '/ai/characters/reply_drafter-avatar.webp'),
  ('followup_scheduler', 'Tempo', '{"en":"Keeps leads moving with timely follow-ups, viewing reminders and the next-best action.","ms":"Memastikan prospek terus bergerak dengan susulan tepat masa, peringatan lawatan dan tindakan terbaik seterusnya.","id":"Menjaga prospek terus bergerak dengan tindak lanjut tepat waktu, pengingat kunjungan dan langkah terbaik berikutnya."}'::jsonb, '{"en":["Follow-up plans","Viewing reminders","Next steps"],"ms":["Pelan susulan","Peringatan lawatan","Langkah seterusnya"],"id":["Rencana tindak lanjut","Pengingat kunjungan","Langkah berikutnya"]}'::jsonb, '/ai/characters/followup_scheduler.webp', '/ai/characters/followup_scheduler-avatar.webp'),
  ('email_composer', 'Orion', '{"en":"Writes longer, polished e-mails for owner updates, viewing confirmations, offers and more.","ms":"Menulis e-mel yang lebih panjang dan kemas untuk kemas kini pemilik, pengesahan lawatan, tawaran dan lain-lain.","id":"Menulis e-mail yang lebih panjang dan rapi untuk pembaruan pemilik, konfirmasi kunjungan, penawaran dan lainnya."}'::jsonb, '{"en":["Owner updates","Offers & negotiations","Formal & clear"],"ms":["Kemas kini pemilik","Tawaran & rundingan","Formal & jelas"],"id":["Pembaruan pemilik","Penawaran & negosiasi","Formal & jelas"]}'::jsonb, '/ai/characters/email_composer.webp', '/ai/characters/email_composer-avatar.webp'),
  ('listing_copywriter', 'Luna', '{"en":"Turns property details into compelling, buyer-ready listing copy that highlights key features and lifestyle.","ms":"Menukar butiran hartanah kepada teks penyenaraian menarik yang menonjolkan ciri utama dan gaya hidup.","id":"Mengubah detail properti menjadi teks listing menarik yang menonjolkan fitur utama dan gaya hidup."}'::jsonb, '{"en":["Listing descriptions","Key selling points","Lifestyle appeal"],"ms":["Penerangan penyenaraian","Nilai jualan utama","Daya tarikan gaya hidup"],"id":["Deskripsi listing","Nilai jual utama","Daya tarik gaya hidup"]}'::jsonb, '/ai/characters/listing_copywriter.webp', '/ai/characters/listing_copywriter-avatar.webp'),
  ('caption_writer', 'Kira', '{"en":"Creates catchy, on-brand captions for Instagram, Facebook and TikTok that drive engagement.","ms":"Mencipta kapsyen menarik dan konsisten untuk Instagram, Facebook dan TikTok yang mendorong penglibatan.","id":"Membuat caption menarik dan konsisten untuk Instagram, Facebook dan TikTok yang mendorong interaksi."}'::jsonb, '{"en":["Social captions","Engagement focused","Platform-ready"],"ms":["Kapsyen sosial","Fokus penglibatan","Sedia untuk platform"],"id":["Caption sosial","Fokus interaksi","Siap platform"]}'::jsonb, '/ai/characters/caption_writer.webp', '/ai/characters/caption_writer-avatar.webp'),
  ('brochure_writer', 'Atlas', '{"en":"Writes elegant, concise copy for one-page property brochures and marketing materials, ready for print or digital.","ms":"Menulis teks elegan dan ringkas untuk brosur hartanah satu muka dan bahan pemasaran, sedia cetak atau digital.","id":"Menulis teks elegan dan ringkas untuk brosur properti satu halaman dan materi pemasaran, siap cetak atau digital."}'::jsonb, '{"en":["Brochure copy","Feature highlights","Print & digital ready"],"ms":["Teks brosur","Sorotan ciri","Sedia cetak & digital"],"id":["Teks brosur","Sorotan fitur","Siap cetak & digital"]}'::jsonb, '/ai/characters/brochure_writer.webp', '/ai/characters/brochure_writer-avatar.webp'),
  ('property_matcher', 'Vega', '{"en":"Smart property match specialist. Pools your listings and requirements to surface the best-fit properties in seconds.","ms":"Pakar padanan hartanah. Menggabungkan penyenaraian dan keperluan anda untuk menonjolkan hartanah paling sesuai dalam beberapa saat.","id":"Spesialis pencocokan properti. Menggabungkan listing dan kebutuhan Anda untuk menampilkan properti paling cocok dalam hitungan detik."}'::jsonb, '{"en":["Best-fit matches","Own & pool listings","Same country only"],"ms":["Padanan terbaik","Penyenaraian sendiri & kolam","Negara sama sahaja"],"id":["Kecocokan terbaik","Listing sendiri & pool","Hanya negara sama"]}'::jsonb, '/ai/characters/property_matcher.webp', '/ai/characters/property_matcher-avatar.webp'),
  ('buyer_profiler', 'Sora', '{"en":"Empathetic profiling assistant. Turns conversations into a clear, structured buyer profile with needs, budget and lifestyle cues.","ms":"Pembantu profil yang empati. Menukar perbualan kepada profil pembeli yang jelas dengan keperluan, bajet dan petunjuk gaya hidup.","id":"Asisten profil yang empatik. Mengubah percakapan menjadi profil pembeli yang jelas dengan kebutuhan, anggaran dan gaya hidup."}'::jsonb, '{"en":["Needs & budget","Structured profile","You confirm"],"ms":["Keperluan & bajet","Profil berstruktur","Anda sahkan"],"id":["Kebutuhan & anggaran","Profil terstruktur","Anda konfirmasi"]}'::jsonb, '/ai/characters/buyer_profiler.webp', '/ai/characters/buyer_profiler-avatar.webp'),
  ('alternative_finder', 'Niko', '{"en":"Fast option-scouting assistant. Suggests three strong alternatives when the first choice doesn''t fit, so you always have a plan B.","ms":"Pembantu pantas mencari pilihan. Mencadangkan tiga alternatif kukuh apabila pilihan pertama tidak sesuai, supaya anda sentiasa ada pelan B.","id":"Asisten pencari opsi yang cepat. Menyarankan tiga alternatif kuat saat pilihan pertama tak cocok, agar Anda selalu punya rencana B."}'::jsonb, '{"en":["Three alternatives","Plan B ready","Reasoned picks"],"ms":["Tiga alternatif","Pelan B sedia","Pilihan beralasan"],"id":["Tiga alternatif","Rencana B siap","Pilihan beralasan"]}'::jsonb, '/ai/characters/alternative_finder.webp', '/ai/characters/alternative_finder-avatar.webp'),
  ('task_planner', 'Kael', '{"en":"Structured productivity planner. Turns your leads and brief into a clear, actionable task list with priorities and next steps.","ms":"Perancang produktiviti berstruktur. Menukar prospek dan taklimat anda kepada senarai tugas yang jelas dengan keutamaan dan langkah seterusnya.","id":"Perencana produktivitas terstruktur. Mengubah prospek dan brief Anda menjadi daftar tugas yang jelas dengan prioritas dan langkah berikutnya."}'::jsonb, '{"en":["Task list","Priorities","You confirm each one"],"ms":["Senarai tugas","Keutamaan","Anda sahkan setiap satu"],"id":["Daftar tugas","Prioritas","Anda konfirmasi satu per satu"]}'::jsonb, '/ai/characters/task_planner.webp', '/ai/characters/task_planner-avatar.webp'),
  ('viewing_coordinator', 'Ivy', '{"en":"Polished appointment host. Proposes suitable viewing slots, coordinates with clients and keeps location and details in sync.","ms":"Hos temu janji yang kemas. Mencadangkan slot lawatan sesuai, menyelaras dengan pelanggan dan memastikan lokasi serta butiran selari.","id":"Tuan rumah janji temu yang rapi. Mengusulkan slot kunjungan yang pas, berkoordinasi dengan klien dan menjaga lokasi serta detail tetap sinkron."}'::jsonb, '{"en":["Viewing slots","Confirmations","Details in sync"],"ms":["Slot lawatan","Pengesahan","Butiran selari"],"id":["Slot kunjungan","Konfirmasi","Detail sinkron"]}'::jsonb, '/ai/characters/viewing_coordinator.webp', '/ai/characters/viewing_coordinator-avatar.webp'),
  ('reminder_assistant', 'Piper', '{"en":"Cheerful follow-up reminder specialist. Keeps you and your clients on track with smart, timely nudges before every key step.","ms":"Pakar peringatan susulan yang ceria. Memastikan anda dan pelanggan berada di landasan dengan peringatan bijak dan tepat masa sebelum setiap langkah penting.","id":"Spesialis pengingat yang ceria. Menjaga Anda dan klien tetap di jalur dengan pengingat cerdas dan tepat waktu sebelum setiap langkah penting."}'::jsonb, '{"en":["Timely nudges","Before every viewing","With consent"],"ms":["Peringatan tepat masa","Sebelum setiap lawatan","Dengan persetujuan"],"id":["Pengingat tepat waktu","Sebelum setiap kunjungan","Dengan persetujuan"]}'::jsonb, '/ai/characters/reminder_assistant.webp', '/ai/characters/reminder_assistant-avatar.webp'),
  ('listing_researcher', 'Scout', '{"en":"Sharp market researcher who finds comparable listings, recent activity and pricing trends.","ms":"Penyelidik pasaran tajam yang mencari penyenaraian setanding, aktiviti terkini dan trend harga.","id":"Peneliti pasar yang jeli, menemukan listing sebanding, aktivitas terkini dan tren harga."}'::jsonb, '{"en":["Market search","Listing comps","Price trends"],"ms":["Carian pasaran","Penyenaraian setanding","Trend harga"],"id":["Pencarian pasar","Listing pembanding","Tren harga"]}'::jsonb, '/ai/characters/listing_researcher.webp', '/ai/characters/listing_researcher-avatar.webp'),
  ('owner_outreach', 'Raya', '{"en":"Persuasive first-contact assistant who drafts friendly, effective messages to property owners.","ms":"Pembantu hubungan pertama yang meyakinkan, mendraf mesej mesra dan berkesan kepada pemilik hartanah.","id":"Asisten kontak pertama yang persuasif, menyusun pesan ramah dan efektif untuk pemilik properti."}'::jsonb, '{"en":["First outreach","Message drafts","Owner leads"],"ms":["Hubungan pertama","Draf mesej","Prospek pemilik"],"id":["Kontak pertama","Draf pesan","Prospek pemilik"]}'::jsonb, '/ai/characters/owner_outreach.webp', '/ai/characters/owner_outreach-avatar.webp'),
  ('comparables_analyst', 'Quinn', '{"en":"Data-driven pricing analyst who explains where a price sits against similar properties and why.","ms":"Penganalisis harga berasaskan data yang menerangkan kedudukan sesuatu harga berbanding hartanah serupa dan sebabnya.","id":"Analis harga berbasis data yang menjelaskan posisi sebuah harga dibanding properti serupa dan alasannya."}'::jsonb, '{"en":["Similar sales","Price position","Pricing insight"],"ms":["Jualan serupa","Kedudukan harga","Wawasan harga"],"id":["Penjualan serupa","Posisi harga","Wawasan harga"]}'::jsonb, '/ai/characters/comparables_analyst.webp', '/ai/characters/comparables_analyst-avatar.webp'),
  ('quality_auditor', 'Halo', '{"en":"Quality-control expert who reviews your listing and flags issues with clear, actionable fixes.","ms":"Pakar kawalan kualiti yang menyemak penyenaraian anda dan menandakan isu dengan pembetulan yang jelas.","id":"Ahli kendali mutu yang meninjau listing Anda dan menandai masalah dengan perbaikan yang jelas."}'::jsonb, '{"en":["Listing check","Fix suggestions","Quality score"],"ms":["Semakan penyenaraian","Cadangan pembetulan","Skor kualiti"],"id":["Cek listing","Saran perbaikan","Skor kualitas"]}'::jsonb, '/ai/characters/quality_auditor.webp', '/ai/characters/quality_auditor-avatar.webp'),
  ('photo_checker', 'Pixel', '{"en":"Visual inspector who spots blurry, duplicate or non-compliant photos before you publish.","ms":"Pemeriksa visual yang mengesan foto kabur, berganda atau tidak mematuhi peraturan sebelum anda terbitkan.","id":"Pemeriksa visual yang mendeteksi foto buram, duplikat atau tidak sesuai aturan sebelum Anda terbitkan."}'::jsonb, '{"en":["Photo quality","Duplicate check","Compliance"],"ms":["Kualiti foto","Semakan berganda","Pematuhan"],"id":["Kualitas foto","Cek duplikat","Kepatuhan"]}'::jsonb, '/ai/characters/photo_checker.webp', '/ai/characters/photo_checker-avatar.webp'),
  ('refresh_planner', 'Flux', '{"en":"Optimisation planner who tells you which listings to refresh, when to do it and what to update for better results.","ms":"Perancang pengoptimuman yang memberitahu penyenaraian mana perlu disegarkan, bila dan apa yang perlu dikemas kini.","id":"Perencana optimasi yang memberi tahu listing mana yang perlu disegarkan, kapan dan apa yang perlu diperbarui."}'::jsonb, '{"en":["Refresh timing","Update focus","Performance boost"],"ms":["Masa penyegaran","Fokus kemas kini","Peningkatan prestasi"],"id":["Waktu penyegaran","Fokus pembaruan","Dorongan performa"]}'::jsonb, '/ai/characters/refresh_planner.webp', '/ai/characters/refresh_planner-avatar.webp'),
  ('poster_designer', 'Juno', '{"en":"A stylish visual creative who turns your listings into eye-catching posters and marketing assets, ready to share.","ms":"Kreatif visual bergaya yang menukar penyenaraian anda kepada poster dan aset pemasaran menarik, sedia dikongsi.","id":"Kreator visual bergaya yang mengubah listing Anda menjadi poster dan aset pemasaran menarik, siap dibagikan."}'::jsonb, '{"en":["Template posters","Listing visuals","Ready to share"],"ms":["Poster templat","Visual penyenaraian","Sedia dikongsi"],"id":["Poster template","Visual listing","Siap dibagikan"]}'::jsonb, '/ai/characters/poster_designer.webp', '/ai/characters/poster_designer-avatar.webp'),
  ('video_scriptwriter', 'Neo', '{"en":"A cinematic storyteller who writes compelling 30-second video scripts and shot lists that showcase your listings.","ms":"Pencerita sinematik yang menulis skrip video 30 saat dan senarai syot yang menonjolkan penyenaraian anda.","id":"Pencerita sinematik yang menulis naskah video 30 detik dan daftar shot yang menonjolkan listing Anda."}'::jsonb, '{"en":["30-second scripts","Shot lists","Walkthroughs"],"ms":["Skrip 30 saat","Senarai syot","Lawatan video"],"id":["Naskah 30 detik","Daftar shot","Walkthrough"]}'::jsonb, '/ai/characters/video_scriptwriter.webp', '/ai/characters/video_scriptwriter-avatar.webp'),
  ('social_planner', 'Solis', '{"en":"A campaign planner who maps out a week of engaging social posts for your listings, with the right content, timing and format.","ms":"Perancang kempen yang merangka seminggu hantaran sosial menarik untuk penyenaraian anda, dengan kandungan, masa dan format yang tepat.","id":"Perencana kampanye yang memetakan seminggu posting sosial menarik untuk listing Anda, dengan konten, waktu dan format yang tepat."}'::jsonb, '{"en":["Weekly calendar","Right timing","Through the Studio"],"ms":["Kalendar mingguan","Masa yang tepat","Melalui Studio"],"id":["Kalender mingguan","Waktu tepat","Lewat Studio"]}'::jsonb, '/ai/characters/social_planner.webp', '/ai/characters/social_planner-avatar.webp'),
  ('objection_coach', 'Titan', '{"en":"A confident sales coach who helps you practise and handle buyer objections with clear, persuasive responses.","ms":"Jurulatih jualan yakin yang membantu anda berlatih dan menangani bantahan pembeli dengan jawapan jelas dan meyakinkan.","id":"Pelatih penjualan percaya diri yang membantu Anda berlatih dan menangani keberatan pembeli dengan jawaban jelas dan persuasif."}'::jsonb, '{"en":["Objection practice","Persuasive replies","AG Sales Lab"],"ms":["Latihan bantahan","Jawapan meyakinkan","AG Sales Lab"],"id":["Latihan keberatan","Jawaban persuasif","AG Sales Lab"]}'::jsonb, '/ai/characters/objection_coach.webp', '/ai/characters/objection_coach-avatar.webp'),
  ('offer_summariser', 'Clara', '{"en":"A refined transaction writer who turns an offer into a clear, professional summary for owners and buyers.","ms":"Penulis transaksi yang kemas, menukar tawaran kepada ringkasan jelas dan profesional untuk pemilik dan pembeli.","id":"Penulis transaksi yang rapi, mengubah penawaran menjadi ringkasan jelas dan profesional untuk pemilik dan pembeli."}'::jsonb, '{"en":["Offer summary","Plain language","Owner & buyer"],"ms":["Ringkasan tawaran","Bahasa mudah","Pemilik & pembeli"],"id":["Ringkasan penawaran","Bahasa sederhana","Pemilik & pembeli"]}'::jsonb, '/ai/characters/offer_summariser.webp', '/ai/characters/offer_summariser-avatar.webp'),
  ('closing_checklist', 'Finn', '{"en":"A dependable closing assistant who keeps every document, step and deadline on track from accepted offer to a smooth close.","ms":"Pembantu penutupan yang boleh diharap, memastikan setiap dokumen, langkah dan tarikh akhir berada di landasan dari tawaran diterima hingga selesai.","id":"Asisten closing yang andal, menjaga setiap dokumen, langkah dan tenggat tetap di jalur dari penawaran diterima hingga closing mulus."}'::jsonb, '{"en":["Documents","Steps & deadlines","Per country"],"ms":["Dokumen","Langkah & tarikh akhir","Mengikut negara"],"id":["Dokumen","Langkah & tenggat","Per negara"]}'::jsonb, '/ai/characters/closing_checklist.webp', '/ai/characters/closing_checklist-avatar.webp'),
  ('team_coach', 'Aria', '{"en":"A warm coaching specialist who builds stronger habits, shares feedback and helps your team grow.","ms":"Pakar bimbingan yang mesra, membina tabiat lebih kukuh, berkongsi maklum balas dan membantu pasukan anda berkembang.","id":"Spesialis coaching yang hangat, membangun kebiasaan lebih kuat, memberi umpan balik dan membantu tim Anda tumbuh."}'::jsonb, '{"en":["Mentoring","Skill growth","Team success"],"ms":["Bimbingan","Pertumbuhan kemahiran","Kejayaan pasukan"],"id":["Mentoring","Pertumbuhan skill","Kesuksesan tim"]}'::jsonb, '/ai/characters/team_coach.webp', '/ai/characters/team_coach-avatar.webp'),
  ('onboarding_guide', 'Rio', '{"en":"A welcoming starter-guide assistant who walks new users through setup, key features and first wins.","ms":"Pembantu panduan permulaan yang mesra, membimbing pengguna baharu melalui persediaan, ciri utama dan kejayaan pertama.","id":"Asisten panduan awal yang ramah, memandu pengguna baru lewat pengaturan, fitur utama dan kemenangan pertama."}'::jsonb, '{"en":["Step by step","Feature guides","First win"],"ms":["Langkah demi langkah","Panduan ciri","Kejayaan pertama"],"id":["Langkah demi langkah","Panduan fitur","Kemenangan pertama"]}'::jsonb, '/ai/characters/onboarding_guide.webp', '/ai/characters/onboarding_guide-avatar.webp'),
  ('performance_reviewer', 'Prism', '{"en":"An insight analyst who reviews performance, highlights trends and shows peer comparisons for continuous improvement.","ms":"Penganalisis wawasan yang menyemak prestasi, menonjolkan trend dan menunjukkan perbandingan rakan sebaya untuk penambahbaikan berterusan.","id":"Analis wawasan yang meninjau performa, menyoroti tren dan menampilkan perbandingan rekan untuk perbaikan berkelanjutan."}'::jsonb, '{"en":["Performance review","Peer comparison","Growth insights"],"ms":["Semakan prestasi","Perbandingan rakan","Wawasan pertumbuhan"],"id":["Tinjauan performa","Perbandingan rekan","Wawasan pertumbuhan"]}'::jsonb, '/ai/characters/performance_reviewer.webp', '/ai/characters/performance_reviewer-avatar.webp'),
  ('crossborder_researcher', 'Cosmo', '{"en":"A global market scout who finds what buyers from other markets need to know before they enquire.","ms":"Peninjau pasaran global yang mencari apa yang perlu diketahui pembeli dari pasaran lain sebelum mereka bertanya.","id":"Pengintai pasar global yang menemukan apa yang perlu diketahui pembeli dari pasar lain sebelum mereka bertanya."}'::jsonb, '{"en":["Global markets","Buyer insights","Market routes"],"ms":["Pasaran global","Wawasan pembeli","Laluan pasaran"],"id":["Pasar global","Wawasan pembeli","Rute pasar"]}'::jsonb, '/ai/characters/crossborder_researcher.webp', '/ai/characters/crossborder_researcher-avatar.webp'),
  ('translation_assistant', 'Mila', '{"en":"A multilingual assistant who translates your listings, messages and replies with a natural, professional tone.","ms":"Pembantu berbilang bahasa yang menterjemah penyenaraian, mesej dan balasan anda dengan nada semula jadi dan profesional.","id":"Asisten multibahasa yang menerjemahkan listing, pesan dan balasan Anda dengan nada alami dan profesional."}'::jsonb, '{"en":["Multilingual","Kept factual","Listing ready"],"ms":["Berbilang bahasa","Kekal faktual","Sedia penyenaraian"],"id":["Multibahasa","Tetap faktual","Siap listing"]}'::jsonb, '/ai/characters/translation_assistant.webp', '/ai/characters/translation_assistant-avatar.webp'),
  ('partner_finder', 'Link', '{"en":"A business connector who finds the right partners, co-branded opportunities and cross-market collaborations.","ms":"Penghubung perniagaan yang mencari rakan kongsi yang tepat, peluang jenama bersama dan kerjasama rentas pasaran.","id":"Penghubung bisnis yang menemukan mitra yang tepat, peluang co-branding dan kolaborasi lintas pasar."}'::jsonb, '{"en":["Find partners","Co-marketing","Cross-market deals"],"ms":["Cari rakan kongsi","Pemasaran bersama","Urus niaga rentas pasaran"],"id":["Cari mitra","Co-marketing","Deal lintas pasar"]}'::jsonb, '/ai/characters/partner_finder.webp', '/ai/characters/partner_finder-avatar.webp')
on conflict do nothing;

